def svg_piramides():
    formas = [(t("Expansive", "Expansiva"), t("Many children, few elderly", "Muchos niños, pocos ancianos"), [100, 88, 76, 64, 50, 38, 24, 12], "#9c3d1c"),
              (t("Stationary", "Estacionaria"), t("Each generation replaces the last", "Cada generación repone a la anterior"), [70, 70, 69, 68, 66, 62, 52, 32], "#2e6b30"),
              (t("Constrictive", "Regresiva"), t("Fewer children than adults", "Menos niños que adultos"), [50, 58, 66, 72, 72, 66, 54, 34], "#283593")]
    aria = t("Three population pyramids. The expansive one has a very wide base and narrows quickly toward the top, like a triangle. The stationary one has young and adult groups of almost equal size, like a column that narrows only at the top. The constrictive one has a base narrower than the middle, like an urn. In each, men are on the left and women on the right, the youngest at the bottom.",
             "Tres pirámides de población. La expansiva tiene la base muy ancha y se estrecha deprisa hacia arriba, como un triángulo. La estacionaria tiene grupos jóvenes y adultos casi iguales, como una columna que solo se estrecha en la cima. La regresiva tiene la base más estrecha que el centro, como una urna. En todas, los hombres van a la izquierda y las mujeres a la derecha, y los más jóvenes abajo.")
    s = [f'<svg class="diagrama" style="max-width:720px" viewBox="0 0 720 320" role="img" aria-label="{aria}" xmlns="http://www.w3.org/2000/svg">']
    for i, (nom, sub, anchos, col) in enumerate(formas):
        cx = 120 + i * 240
        s.append(f'<text x="{cx}" y="24" text-anchor="middle" {F} font-size="16" font-weight="700" fill="{col}">{nom}</text>')
        for j, w in enumerate(anchos):
            y = 236 - j * 23
            h = w * 0.9
            s.append(f'<rect x="{cx - h:.1f}" y="{y}" width="{h:.1f}" height="19" fill="{col}" opacity="0.85"/><rect x="{cx}" y="{y}" width="{h:.1f}" height="19" fill="{col}" opacity="0.55"/>')
        s.append(f'<line x1="{cx}" y1="65" x2="{cx}" y2="256" stroke="#fff" stroke-width="2"/>')
        s.append(f'<text x="{cx}" y="278" text-anchor="middle" {F} font-size="13" fill="#1a2330">{sub}</text>')
    s.append(f'<text x="360" y="306" text-anchor="middle" {F} font-size="12.5" fill="#3d4753">{t("Men on the left (darker), women on the right · youngest at the bottom, oldest at the top", "Hombres a la izquierda (más oscuro), mujeres a la derecha · los más jóvenes abajo, los mayores arriba")}</text>')
    s.append("</svg>")
    return "".join(s)


