{C.ejemplo(t("The calculation", "La cuenta"), [("1", t("Chicago has about 2.7 million people in about 590 square kilometers.", "Chicago tiene unos 2.7 millones de habitantes en unos 590 kilómetros cuadrados.")), ("2", "2,700,000 ÷ 590 ≈ 4,576")],
   t("More than one hundred times the average density of the country it is in.", "Más de cien veces la densidad media del país en el que está."))}
