# ---------------------------------------------------------------- la práctica
def casos_factores():
    G = [t("Push factor", "Factor de expulsión"), t("Pull factor", "Factor de atracción"), t("Neither: a consequence", "Ninguno: una consecuencia")]
    PI = [t("Does it drive people out of the place of origin?", "¿Empuja a la gente a salir del lugar de origen?"), t("Does it draw people toward the destination?", "¿Atrae a la gente hacia el destino?"), t("Does it happen after people move, not before?", "¿Ocurre después de que la gente se muda, y no antes?")]
    def caso(tit, piezas):
        return {"titulo": tit, "intro": t("Is it a cause of migration (push or pull) or a consequence of it?", "¿Es una causa de la migración (expulsión o atracción) o una consecuencia de ella?"), "grupos": G, "etiqueta": t("This is…", "Esto es…"),
                "piezas": [{"t": a, "v": v, "pista": PI[v]} for a, v in piezas]}
    return [
        caso(t("Set 1", "Serie 1"), [(t("A civil war forces whole families to flee.", "Una guerra civil obliga a huir a familias enteras."), 0), (t("In the destination city there is construction and everyone who arrives is hired.", "En la ciudad de destino hay obras y contratan a todo el que llega."), 1),
                                      (t("A drought wipes out the harvest the family lived on.", "Una sequía acaba con la cosecha de la que vivía la familia."), 0), (t("The destination neighborhood gets more expensive because many people arrive at once.", "El barrio de destino sube de precio porque llega mucha gente a la vez."), 2)]),
        caso(t("Set 2", "Serie 2"), [(t("A brother who already emigrated offers a place to stay for the first months.", "Un hermano que ya emigró ofrece alojamiento los primeros meses."), 1), (t("The home country does not allow study past a certain age.", "El país de origen no permite estudiar más allá de cierta edad."), 0),
                                      (t("The home region is left with an older and older population.", "La región de origen se queda con una población cada vez más vieja."), 2), (t("The minimum wage at the destination is three times that of the origin.", "El salario mínimo del destino es tres veces mayor que el del origen."), 1)]),
    ]


def banco_lectura():
    D = [(t("The United States has 37 people per km² and Chicago about 4,500. What do you conclude?", "Los Estados Unidos tienen 37 habitantes por km² y Chicago unos 4,500. ¿Qué concluye?"), [t("A national average does not describe any particular place", "Un promedio nacional no describe ningún lugar concreto"), t("One of the figures is wrong", "Uno de los datos está mal"), t("Chicago is not part of the United States average", "Chicago no entra en el promedio del país")], t("Both are correct.", "Los dos son correctos.")),
         (t("A pyramid has a very wide base. What will the country need in twenty years?", "Una pirámide tiene la base muy ancha. ¿Qué necesitará el país dentro de veinte años?"), [t("Jobs for a large generation entering working age", "Empleo para una generación numerosa que entra en edad de trabajar"), t("More nursing homes", "Más residencias de ancianos"), t("Fewer schools", "Menos escuelas")], t("Move the base twenty years up.", "Suba la base veinte años.")),
         (t("A pyramid has a clear notch in the 60-to-70 age group. What does it suggest?", "Una pirámide tiene una muesca clara en el grupo de 60 a 70 años. ¿Qué sugiere?"), [t("A historical event reduced that generation when it was young or not yet born", "Un suceso histórico redujo esa generación cuando era joven o aún no había nacido"), t("Life expectancy suddenly fell", "La esperanza de vida bajó de golpe"), t("There was an error in the data", "Hubo un error en los datos")], t("History drawn on a graph.", "Historia dibujada en una gráfica.")),
         (t("A pyramid’s base is wide. Can you conclude the country is poor?", "Una pirámide tiene la base ancha. ¿Se puede concluir que el país es pobre?"), [t("No: a pyramid shows ages, not wealth", "No: una pirámide muestra edades, no riqueza"), t("Yes, always", "Sí, siempre"), t("Yes, if the top is narrow", "Sí, si la cima es estrecha")], t("They often go together, but saying so is an assumption.", "Suelen ir juntas, pero decirlo es una suposición.")),
         (t("Mostly young adults leave a rural region. What happens to its pyramid?", "De una región rural se va sobre todo gente joven. ¿Qué le pasa a su pirámide?"), [t("It becomes more constrictive", "Se vuelve más regresiva"), t("It becomes more expansive", "Se vuelve más expansiva"), t("It does not change", "No cambia")], t("Those who leave are young.", "Quien se va es joven.")),
         (t("In one year, 1,000 people leave town A for city B because the mill in A closed. For city B, the closing of the mill is…", "En un año, 1,000 personas dejan el pueblo A por la ciudad B porque cerró la fábrica de A. Para la ciudad B, el cierre de la fábrica es…"), [t("a push factor in the origin, not something about city B", "un factor de expulsión en el origen, no algo de la ciudad B"), t("a pull factor of city B", "un factor de atracción de la ciudad B"), t("a consequence of the migration", "una consecuencia de la migración")], t("It happened in A, before the move.", "Ocurrió en A, antes del traslado."))]
    return [{"enun": "<strong>" + s + "</strong>", "ops": ops, "ok": 0, "exp": e} for s, ops, e in D]


def tx():
    return {"den": t("{l} has {p} people in an area of {s} km². What is its population density?", "{l} tiene {p} habitantes en una superficie de {s} km². ¿Cuál es su densidad de población?"),
            "lug": [t("A county", "Un condado"), t("A city", "Una ciudad"), t("An island", "Una isla"), t("A province", "Una provincia"), t("A town", "Un pueblo")],
            "pide": t("Write the number of people per km².", "Escriba el número de habitantes por km²."),
            "alReves": t("You divided area by people. Divide people by area.", "Dividió la superficie entre los habitantes. Divida los habitantes entre la superficie."),
            "denP": t("Density = people ÷ area.", "Densidad = habitantes ÷ superficie."),
            "porKm": t(" people per km².", " habitantes por km².")}


JS = r"""
function gDen(){
  var d = elige([12, 25, 40, 64, 85, 120, 150, 240, 375, 600, 1200, 2500, 4000]), s = elige([20, 40, 80, 150, 250, 400, 600, 1200, 2000]);
  var p = d * s;
  var enun = "<p>" + TXS.den.replace("{l}", elige(TXS.lug)).replace("{p}", com(p)).replace("{s}", com(s)) + "</p><p>" + TXS.pide + "</p>";
  return {enun: enun, resp: leeNumero(String(d)), explica: com(p) + " ÷ " + com(s) + " = " + com(d) + TXS.porKm,
    pista: function(x){ if (igual(x, leeNumero(String(Math.round(s / p * 10000) / 10000)))) return TXS.alReves; return TXS.denP; }};
}
"""


def practica():
    A = {"en": ["density", "push-pull", "reading"], "es": ["densidad", "expulsion-atraccion", "lectura"]}[C.L]
    mods = [
        (A[0], t("Calculate a density", "Calcule una densidad"), "      <p>" + t("New numbers every time. Density = people ÷ area.", "Números nuevos cada vez. Densidad = habitantes ÷ superficie.") + "</p>\n" + C.dec_campo("m1", t("People per km²", "Habitantes por km²"))),
        (A[1], t("Push, pull, or neither?", "¿Expulsión, atracción o ninguna?"), C.clasifica("m2", t("A cause happens before the move; a consequence, after. If something is not right, the statements marked in yellow get a hint.", "Una causa ocurre antes del traslado; una consecuencia, después. Si algo no está bien, los enunciados marcados en amarillo reciben una pista."))),
        (A[2], t("Pyramids, averages, and migration", "Pirámides, promedios y migración"), C.om("m3", t("Say what the data show, no more.", "Diga lo que muestran los datos, nada más."))),
    ]
    js = C.js_datos("TXS", tx()) + C.js_datos("FAC", casos_factores()) + C.js_datos("LEC", banco_lectura()) + JS + 'creaPracticaDec("m1", gDen);\ncreaClasifica("m2", FAC);\ncreaBanco("m3", LEC);\n'
    return C.pagina_practica(N, titulo(), t("Three activities · new exercises every time · two tries in each one · calculator included", "Tres actividades · ejercicios nuevos cada vez · dos intentos en cada uno · con calculadora"), mods, js,
                             scripts=("/math/scinot.js",), calculadora=True)


if __name__ == "__main__":
    C.construye(N, leccion, practica)
